(function mountStaffProfile(){
  const storageKey='crm_session_user';
  const readUser=()=>{try{return JSON.parse(localStorage.getItem(storageKey)||'{}');}catch(_){return{};}};
  const writeUser=(user)=>localStorage.setItem(storageKey,JSON.stringify(user));
  const sourceOf=(user)=>user.avatarUrl||user.avatar_url||user.avatar||user.photoUrl||user.photo_url||user.photo||'';
  const compressAvatar=(file)=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const image=new Image();image.onerror=reject;image.onload=()=>{const width=image.naturalWidth||image.width;const height=image.naturalHeight||image.height;if(width*height>20000000){reject(new Error("image_too_large"));return;}const scale=Math.min(1,256/Math.max(width,height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/webp',.78));};image.src=String(reader.result);};reader.readAsDataURL(file);});
  const initials=(user)=>String(user.name||user.fullName||user.username||'С').trim().slice(0,1).toUpperCase();
  const renderAvatar=(host,user)=>{if(!host)return;let avatar=host.querySelector('.staff-profile-avatar');if(!avatar){avatar=document.createElement('span');avatar.className='staff-profile-avatar';host.prepend(avatar);}const source=sourceOf(user);avatar.textContent=source?'':initials(user);avatar.style.backgroundImage=source?'url("'+source.replace(/"/g,'')+'")':'';};
  const renderPortalAvatar=(node,user)=>{if(!node)return;const source=sourceOf(user);const nextInitials=initials(user);const currentImage=node.querySelector('img');if(source){if(currentImage&&currentImage.getAttribute('src')===source&&currentImage.alt===String(user.name||'Сотрудник'))return;}else if(!currentImage&&!node.children.length&&node.textContent===nextInitials)return;node.replaceChildren();if(source){const image=document.createElement('img');image.src=source;image.alt=String(user.name||'Сотрудник');node.append(image);}else node.textContent=nextInitials;};
  const syncPortalAvatars=(user)=>{document.querySelectorAll('[data-user-avatar],[data-sidebar-avatar]').forEach((node)=>renderPortalAvatar(node,user));};
  const normalizePhones=(user)=>Array.isArray(user.phoneNumbers)?user.phoneNumbers.filter((phone)=>phone&&phone.number).map((phone,index)=>({label:String(phone.label||'Рабочий'),number:String(phone.number||'').trim(),primary:Boolean(phone.primary)||index===0})):[];
  const open=()=>{
    if(document.querySelector('.staff-profile-modal'))return;
    const user=readUser(); const modal=document.createElement('div'); modal.className='staff-profile-modal';
    modal.innerHTML='<div class="staff-profile-dialog" role="dialog" aria-modal="true" aria-label="Профиль сотрудника"><button type="button" class="staff-profile-close" aria-label="Закрыть">×</button><div class="staff-profile-dialog__heading"><span class="staff-profile-dialog__avatar staff-profile-preview">'+initials(user)+'</span><div><h2>Мой профиль</h2><p>Аватар и рабочие контакты</p></div></div><div class="staff-profile-field"><span>Аватар</span><div class="staff-profile-upload"><label class="staff-profile-upload-button" for="staff-profile-file">Выбрать изображение</label><span class="staff-profile-file-name">Файл не выбран</span><input id="staff-profile-file" type="file" class="staff-profile-file" accept="image/png,image/jpeg,image/webp"></div></div><label class="staff-profile-field">Telegram<input type="text" class="staff-profile-telegram" placeholder="@username или https://t.me/username"></label><label class="staff-profile-field">PIN сотрудника<input type="password" class="staff-profile-pin" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" placeholder="Новый PIN из 4 цифр"><small>Оставьте пустым, чтобы сохранить текущий PIN.</small></label><div class="staff-profile-phones"><div class="staff-profile-phones__head"><b>Телефоны</b><button type="button" class="staff-profile-phone-add">Добавить номер</button></div><div class="staff-profile-phone-list"></div></div><p class="staff-profile-error" role="alert"></p><div class="staff-profile-actions"><button type="button" class="staff-profile-cancel">Отмена</button><button type="button" class="staff-profile-save">Сохранить</button></div></div>';
    document.body.append(modal);
    const preview=modal.querySelector('.staff-profile-preview'); const file=modal.querySelector('.staff-profile-file'); const fileName=modal.querySelector('.staff-profile-file-name'); const telegram=modal.querySelector('.staff-profile-telegram'); const pin=modal.querySelector('.staff-profile-pin'); const error=modal.querySelector('.staff-profile-error'); const phoneList=modal.querySelector('.staff-profile-phone-list');
    telegram.value=user.telegram||user.telegramUrl||'';
    const current=sourceOf(user); if(current){preview.textContent='';preview.style.backgroundImage='url("'+current.replace(/"/g,'')+'")';}
    const addPhone=(phone={})=>{if(phoneList.children.length>=5)return;const row=document.createElement('div');row.className='staff-profile-phone-row';row.innerHTML='<select aria-label="Тип телефона"><option>Рабочий</option><option>Личный</option><option>Резервный</option><option>Дополнительный</option></select><input type="tel" aria-label="Номер телефона" placeholder="+7 (___) ___-__-__"><label><input type="radio" name="profile_primary_phone"> основной</label><button type="button" class="staff-profile-phone-remove" aria-label="Удалить номер" title="Удалить номер"><svg class="icon" aria-hidden="true"><use href="/assets/tabler-icons.svg#x"></use></svg></button>';row.querySelector('select').value=phone.label||'Рабочий';row.querySelector('input[type="tel"]').value=phone.number||'';row.querySelector('input[type="radio"]').checked=Boolean(phone.primary);row.querySelector('button').addEventListener('click',()=>{if(phoneList.children.length>1)row.remove();else row.querySelector('input[type="tel"]').value='';});phoneList.append(row);};
    const phones=normalizePhones(user); (phones.length?phones:[{}]).forEach(addPhone);
    modal.querySelector('.staff-profile-phone-add').addEventListener('click',()=>addPhone());
    file.addEventListener('change',async()=>{const selected=file.files?.[0];if(!selected)return;fileName.textContent=selected.name;fileName.title=selected.name;if(!['image/png','image/jpeg','image/webp'].includes(selected.type)||selected.size>5*1024*1024){error.textContent='Выберите PNG, JPG или WebP до 5 МБ.';file.value='';fileName.textContent='Файл не выбран';fileName.title='';return;}try{const compact=await compressAvatar(selected);preview.textContent='';preview.style.backgroundImage='url("'+compact.replace(/"/g,'')+'")';preview.dataset.source=compact;}catch(reason){error.textContent=reason.message==='image_too_large'?'Фото слишком большое по разрешению. Выберите изображение до 20 мегапикселей.':'Не удалось обработать изображение.';file.value='';fileName.textContent='Файл не выбран';fileName.title='';}});
    const close=()=>modal.remove(); modal.querySelector('.staff-profile-close').addEventListener('click',close); modal.querySelector('.staff-profile-cancel').addEventListener('click',close); modal.addEventListener('click',(event)=>{if(event.target===modal)close();});
    modal.querySelector('.staff-profile-save').addEventListener('click',async()=>{const value=telegram.value.trim();if(value&&!/^(@[A-Za-z0-9_]{5,32}|https:\/\/t\.me\/[A-Za-z0-9_]{5,32}\/?$)/.test(value)){error.textContent='Укажите @username или ссылку https://t.me/username.';return;}const phoneNumbers=[...phoneList.querySelectorAll('.staff-profile-phone-row')].map((row)=>({label:row.querySelector('select').value,number:row.querySelector('input[type="tel"]').value.trim(),primary:row.querySelector('input[type="radio"]').checked})).filter((phone)=>phone.number);if(phoneNumbers.length>5){error.textContent='Можно сохранить не более пяти номеров.';return;}if(phoneNumbers.some((phone)=>phone.number.replace(/[^0-9]/g,'').length<10)){error.textContent='Проверьте номера телефонов.';return;}if(phoneNumbers.length&&phoneNumbers.filter((phone)=>phone.primary).length!==1){error.textContent='Выберите один основной номер телефона.';return;}const next={...user,telegram:value,phoneNumbers};if(preview.dataset.source){next.avatarUrl=preview.dataset.source;next.avatar=preview.dataset.source;}if(typeof window.__syncStaffProfile==='function'&&!await window.__syncStaffProfile(user,value,next.avatarUrl||'',phoneNumbers)){error.textContent='Не удалось синхронизировать профиль. Повторите попытку.';return;}if(pin?.value&&(!/^\\d{4}$/.test(pin.value)||typeof window.__syncStaffPin!=='function'||!await window.__syncStaffPin(user,pin.value))){error.textContent='PIN должен содержать ровно 4 цифры.';return;}writeUser(next);renderAvatar(document.querySelector('.user'),next);syncPortalAvatars(next);close();});
  };
  const mount=()=>{const user=readUser();const hosts=[...document.querySelectorAll('.user,.header-user,.sidebar-profile')];hosts.forEach((host)=>{if(host.dataset.staffProfileReady==='1')return;host.dataset.staffProfileReady='1';host.setAttribute('role','button');host.tabIndex=0;host.title='Открыть профиль';if(host.classList.contains('user'))renderAvatar(host,user);else host.classList.add('profile-trigger');const isInteractive=(target)=>Boolean(target?.closest?.('a,button,input,select,textarea'));host.addEventListener('click',(event)=>{if(isInteractive(event.target))return;open();});host.addEventListener('keydown',(event)=>{if(isInteractive(event.target))return;if(event.key==='Enter'||event.key===' '){event.preventDefault();open();}});});syncPortalAvatars(user);};
  mount(); new MutationObserver(mount).observe(document.body,{childList:true,subtree:true});
})();
;(function syncStaffProfileWithServer(){
  const original=window.fetch;
  if(typeof original!=='function'&&typeof window.__crmApi!=='function'||window.__staffProfileSyncWrapped)return;
  window.__staffProfileSyncWrapped=true;
  window.__syncStaffProfile=async(user,value,avatar,phoneNumbers)=>{if(!user?.id)return true;const headers=typeof window.sessionHeaders==='function'?window.sessionHeaders():{};headers['Content-Type']='application/json';const request={method:'PATCH',headers,body:JSON.stringify({telegram:value,avatarUrl:avatar||undefined,phoneNumbers:Array.isArray(phoneNumbers)?phoneNumbers:undefined})};const transport=typeof window.__crmApi==='function'?window.__crmApi:original;try{await transport('/api/staff/'+encodeURIComponent(user.id)+'/profile',request);return true;}catch(_){return false;}};  window.__syncStaffPin=async(user,pin)=>{if(!user?.id)return false;const headers=typeof window.sessionHeaders==='function'?window.sessionHeaders():{};headers['Content-Type']='application/json';const request={method:'PATCH',headers,body:JSON.stringify({pin})};const transport=typeof window.__crmApi==='function'?window.__crmApi:original;try{await transport('/api/staff/'+encodeURIComponent(user.id)+'/pin',request);return true;}catch(_){return false;}};
})();
